statement:
\begin{definition}[Definition~2.7 in \citet{ZhangJiang}]\label{def:primitive}
    A schedule $h\in\R_+^n$ is primitive if, with $H\coloneqq\one^\top h$, every $f\in\F_1$ and every associated trajectory satisfy
    \begin{align*}
        \frac12\norm{x_0-x_*}^2+\sum_{i=0}^{n-1}h_iQ_{i,*}-H(f_n-f_*)
        \ge\frac12\norm{x_n-x_*}^2+\frac{H(H+1)}2\norm{g_n}^2.
    \end{align*}
    The empty schedule is primitive with $H=0$.
\end{definition}

\begin{definition}[Definition~4.1 in \citet{ZhangJiang}]\label{def:optimized-primitive}
    Set $h_\circ^{(0)}=[\,]^\top$. For $n\ge1$, choose
    \begin{align*}
        h_\circ^{(n)}
        \in\argmax_{h\in\mathcal H_\circ^{(n)}}\one^\top h,
        \quad
        \mathcal H_\circ^{(n)}
        \coloneqq
        \left\{
        \operatorname{ConPP}\!\(h_\circ^{(k)},h_\circ^{(n-k-1)}\):
        0\le k<n
        \right\}.
    \end{align*}
    If the maximizer is not unique, any maximizing schedule may be selected.
\end{definition}

\begin{definition}[Definition~3 in \citet{GrimmerShuWangMOR}]\label{def:scomposable}
    A positive schedule $h=(h_0,\ldots,h_{n-1})^\top$ is s-composable with rate $\eta>0$ if for every $f\in\F_1$ and every associated trajectory, it holds that
        \begin{align*}
        \frac{1-\eta}{2}\norm{g_n}^2+\frac{\eta^2}{2}\norm{x_n-x_*}^2
        +(\eta-\eta^2)(f_n-f_*)
        \le\frac{\eta^2}{2}\norm{x_0-x_*}^2,
    \end{align*}
    and
    \begin{align*}
        \eta=\frac{1}{1+\sum_{i=0}^{n-1}h_i}
        =\prod_{i=0}^{n-1}(h_i-1).
    \end{align*}
\end{definition}

\begin{definition}[Optimized Basic s-composable Schedule (OBS-S) in \citet{GrimmerShuWangMOR}]\label{def:obs-s}
    Set $h^{\mathrm{OBS\text{-}S}}(0)=[\,]^\top$ and $\eta^{\mathrm{OBS\text{-}S}}(0)=1$. For $N\ge2$, define
    \begin{align*}
        \eta^{\mathrm{OBS\text{-}S}}(N-1)
        \coloneqq\min_{1\le m<N}
        \Jop\!\left(
        \eta^{\mathrm{OBS\text{-}S}}(m-1),
        \eta^{\mathrm{OBS\text{-}S}}(N-m-1)
        \right).
    \end{align*}
    If $m_N$ is any minimizing index, set
    \begin{align*}
        h^{\mathrm{OBS\text{-}S}}(N-1)
        \coloneqq
        h^{\mathrm{OBS\text{-}S}}(m_N-1)
        \bowtie
        h^{\mathrm{OBS\text{-}S}}(N-m_N-1).
    \end{align*}
\end{definition}

\begin{proposition}\label{prop:scalar-equivalence}
    For every $N\ge1$,
    \begin{align*}
        U_N\coloneqq H_N+1=\frac1{s_N}.
    \end{align*}
    The common value satisfies
    \begin{align}\label{eq:U-DP}
        U_1=1,
        \quad
        U_N=\max_{1\le m<N}\Kop(U_m,U_{N-m})
        \quad(N\ge2).
    \end{align}
\end{proposition}

\begin{proposition}\label{lem:K-properties}
    The map $\Kop:[0,+\infty)^2\to[0,+\infty)$ is continuous, symmetric, positively homogeneous, and strictly increasing in each coordinate. It satisfies
    \begin{align}\label{eq:K-special}
        \Kop(0,x)=x,
        \quad
        \Kop(x,x)=\rho x,
        \quad
        \Kop(x,y)>x+y>\max\{x,y\}
        \quad(x,y>0).
    \end{align}
    Moreover, for $x,y,x',y'>0$,
    \begin{align}\label{eq:ratio-sandwich}
        \min\!\left\{\frac{x'}x,\frac{y'}y\right\}
        \le\frac{\Kop(x',y')}{\Kop(x,y)}
        \le\max\!\left\{\frac{x'}x,\frac{y'}y\right\},
    \end{align}
    and both inequalities are strict if $x'/x\ne y'/y$.
\end{proposition}

\begin{theorem} \label{thm:four-point-rearrangement}
For every $0\leq a\leq b\leq c\leq d$,
\begin{align}
    Z_{ab\mid cd} \leq Z_{ac\mid bd} \leq Z_{ad\mid bc}.
    \label{eq:four-point-chain}
\end{align}
Moreover,
\begin{align}
    Z_{ab\mid cd} = Z_{ac\mid bd} & \quad\Longleftrightarrow\quad b=c\ \text{or}\ ad=bc, \label{eq:first-equality-case}\\
    Z_{ac\mid bd} = Z_{ad\mid bc} & \quad\Longleftrightarrow\quad a=b\ \text{or}\ c=d. \label{eq:second-equality-case}
\end{align}
\end{theorem}

\begin{lemma} \label{lem:sign-beyond-inner-roots}
Let $a,b,c,d\geq0$ and let $P_{ab\mid cd}$ be defined in \eqref{eq:conjugate-polynomial}. Define
\begin{align*}
    M_{ab\mid cd} \coloneqq \max\{\mathcal K(a,b),\mathcal K(c,d)\}.
\end{align*}
Then, for every $z>M_{ab\mid cd}$,
\begin{align*}
    \operatorname{sgn}P_{ab\mid cd}(z) = \operatorname{sgn}\bigl(z-Z_{ab\mid cd}\bigr).
\end{align*}
\end{lemma}

\begin{lemma} \label{lem:pairing-differences}
For all $a,b,c,d\geq 0$,
\begin{align*}
    P_{ac\mid bd}(z)-P_{ab\mid cd}(z) & = 2z^2(d-a)(c-b)Q_{ad+bc}(z), \\
    P_{ad\mid bc}(z)-P_{ac\mid bd}(z) & = 2z^2(b-a)(d-c)Q_{ab+cd}(z).
\end{align*}
\end{lemma}

\begin{lemma} \label{lem:quartic-evaluation}
Fix a pairing $(a,b)\mid(c,d)$, where $a,b,c,d\geq 0$, and set
\begin{align*}
    u=\mathcal K(a,b), \quad v=\mathcal K(c,d),\quad z=\mathcal K(u,v).
\end{align*}
If $u,v>0$, then, for every scalar $E$,
\begin{align*}
    Q_E(z)=\frac{2\bigl(abv^2+cdu^2-Euv\bigr)(uv+uz+vz)}{uv},

\end{align*}
where $Q_E$ is formed from the four inputs $a,b,c,d$.
\end{lemma}

\begin{theorem} \label{thm:abstract-balanced}
    Let $\star:[0,\infty)^2\to[0,\infty)$ be symmetric, positively homogeneous, and strictly increasing in each coordinate. Assume that, for some $\lambda>1$,
    \begin{align*}
        0\star x=x,\quad x\star x=\lambda x,
    \end{align*}
    hold for all $x\ge0$, and that the four-point rearrangement inequalities
    \begin{align*}
        (a\star b)\star(c\star d)
        \le(a\star c)\star(b\star d)
        \le(a\star d)\star(b\star c)
    \end{align*}
    hold whenever $0\le a\le b\le c\le d$. Define the balanced sequence $\{V_N\}_{N\ge0}$ by
    \begin{align}\label{eq:V-balanced}
        V_0=0,
        \quad
        V_1=1,
        \quad
        V_N=V_{\floor{N/2}}\star V_{\ceil{N/2}}
        \;(N\ge2),
    \end{align}
    and define the Bellman sequence $\{W_N\}_{N\ge1}$ by
    \begin{align}\label{eq:W-bellman}
        W_1=1,
        \quad
        W_N=\max_{1\le m<N}W_m\star W_{N-m}
        \;(N\ge2).
    \end{align}
    Then $\{V_N\}_{N\ge0}$ is strictly increasing and satisfies the supercomposition inequality
    \begin{align*}
        V_m\star V_n\le V_{m+n}
        \quad(m,n\ge0).
    \end{align*}
    Consequently, $W_N=V_N$ for every $N\ge1$.
\end{theorem}

\begin{corollary}\label{cor:balanced-optimality}
    Extend the common scalar sequence by $U_0 \coloneqq 0$. Then $\{U_N\}_{N\ge0}$ is strictly increasing, and for all $m,n\ge0$,
    \begin{align*}
        \Kop(U_m,U_n)\le U_{m+n}.
    \end{align*}
    Moreover, every $N\ge2$ satisfies the balanced recurrence
    \begin{align} \label{eq:balanced-recurrence}
        U_N=\Kop\bigl(U_{\floor{N/2}},U_{\ceil{N/2}}\bigr).
    \end{align}
    In particular, the balanced root split solves the Bellman program~\eqref{eq:U-DP} at every leaf count.
\end{corollary}

\begin{lemma}\label{lem:equality-supercomposition}
    For positive integers $m,n$,
    \begin{align*}
        \Kop(U_m,U_n)=U_{m+n}
    \end{align*}
    if and only if either
    \begin{enumerate}[label=(\roman*)]
        \item $m=n$; or
        \item there exist integers $k\ge0$ and $r\ge1$ such that
        \begin{align*}
            \{m,n\}=\{2^kr,2^k(r+1)\}.
        \end{align*}
    \end{enumerate}
\end{lemma}

\begin{corollary}\label{cor:all-splits}
    For $N\ge2$, define the set of maximizing left-child leaf counts by
    \begin{align*}
        \mathcal{M}_N
        \coloneqq \argmax_{1\le m<N}\Kop(U_m,U_{N-m}).
    \end{align*}

    Write $N=\nu \cdot 2^\ell$, where $\nu$ is odd. Then
    \begin{enumerate}[label=(\roman*)]
        \item If $\nu=1$, then
        \begin{align*}
            \mathcal{M}_N=\{N/2\}.
        \end{align*}
        \item If $\nu>1$ and $\ell=0$, then
        \begin{align*}
            \mathcal{M}_N=\{(N-1)/2,(N+1)/2\}.
        \end{align*}
        \item If $\nu>1$ and $\ell\ge1$, then
        \begin{align}\label{eq:three-splits}
            \mathcal{M}_N
            =\left\{(\nu-1)2^{\ell-1},\nu\cdot2^{\ell-1},(\nu+1)2^{\ell-1}\right\}.
        \end{align}
    \end{enumerate}

\end{corollary}

\begin{theorem}[Conjecture~4.17 in \citet{ZhangJiang}]\label{cor:ZhangJiang-conjecture}
    For every step count $n\ge1$,

    \begin{align*}
        \one^\top h_\circ^{(n)}
        =\one^\top\operatorname{ConPP}\!\left(
        h_\circ^{(\floor{(n-1)/2})},
        h_\circ^{(\ceil{(n-1)/2})}
        \right).
    \end{align*}
    Moreover, if $n=\nu\cdot2^\ell-1$ with $\nu>1$ odd and $\ell\ge1$, then, for every $i\in\{-1,0,1\}$,
    \begin{align*}
        \one^\top h_\circ^{(n)}
        =\one^\top\operatorname{ConPP}\!\left(
        h_\circ^{((\nu+i)2^{\ell-1}-1)},
        h_\circ^{((\nu-i)2^{\ell-1}-1)}
        \right),
    \end{align*}
    and no other ConPP root split between two recursively optimized primitive schedules attains the same total stepsize.
\end{theorem}

\begin{corollary} \label{cor:optimal-trees}
    Let $T$ be an ordered full binary composition tree with $N$ leaves, assign value $1$ to every leaf, and evaluate each internal node using $\Kop$. Then $T$ attains the optimal root value $U_N$ if and only if, at every internal node with $j$ descendant leaves, its two child subtrees are optimal for their respective leaf counts and its left-child leaf count belongs to $\mathcal{M}_j$. Equivalently, $T$ is optimal if and only if every internal split satisfies one of the two equality patterns in Lemma \ref{lem:equality-supercomposition}.
\end{corollary}

\begin{lemma} \label{lem:silver-power}
For all $x,y\geq0$,
\begin{align*}
    \Kop(x,y)\le (x^q+y^q)^{1/q}.
\end{align*}
Equality holds if and only if $x=y$ or $xy=0$.
\end{lemma}

\begin{proposition}\label{prop:sharp-growth}
For every $N\ge1$,
\begin{align*}
    U_N\le N^p.
\end{align*}
Equivalently, $s_N\ge N^{-p}$. Equality holds if and only if $N$ is a power of two.
\end{proposition}

\begin{lemma} \label{lem:ratio-contraction}
For every $N\ge1$,
\begin{align}\label{eq:R-recursion}
    R_{2N}=T_0(R_N), \quad R_{2N+1}=T_1(R_N),
\end{align}
and
\begin{align}\label{eq:R-bound}
    1<R_N\le\rho, \quad
    0<R_N-1\le\frac{\rho-1}{2^{\floor{\log_2N}}}
    \le\frac{2(\rho-1)}N.
\end{align}
\end{lemma}

\begin{lemma}\label{lem:Lipschitz-F}
The function in \eqref{eq:F-dyadic} extends uniquely to a strictly increasing bi-Lipschitz map
\begin{align*}
    F:[1,2]\to[1,\rho]
\end{align*}
that satisfies $F(1)=1$, $F(2)=\rho$, and \eqref{eq:midpoint-rule} on every dyadic interval. More precisely,
\begin{align}\label{eq:bilipschitz}
    c_-(y-x)\le F(y)-F(x)\le c_+(y-x),
    \quad 1\le x<y\le2,
\end{align}
where
\begin{align*}
    c_-\coloneqq(\rho-1)\left(1-\frac1{2\rho}\right),
    \quad
    c_+\coloneqq(\rho-1)\exp\left(\frac1{2\rho}\right).
\end{align*}
In particular, one may take $L_F\coloneqq c_+$ as a Lipschitz constant for $F$.
\end{lemma}

\begin{theorem} \label{thm:phase}
For $0\le t\le1$, define
\begin{align*}
    \Phi(t)\coloneqq \rho^{-t}F(2^t),
\end{align*}
and extend $\Phi$ as a $1$-periodic function. Let $\mathbb T \coloneqq \R/\mathbb Z$. Then $\Phi: \mathbb T \to \mathbb R$ is positive, Lipschitz, and nonconstant, and
\begin{align}\label{eq:exact-phase}
    U_N=N^p\Phi\bigl(\{\log_2N\}\bigr) \quad (N\ge1),
\end{align}
where $\{\cdot\}$ takes the fractional part of a real. It is the unique continuous $1$-periodic function with this property. Furthermore,
\begin{align}\label{eq:phase-extrema}
    0<\phimin\coloneqq\min_{t\in[0,1]}\Phi(t)<1,
    \quad
    \max_{t\in[0,1]}\Phi(t)=1.
\end{align}
One valid Lipschitz constant on the phase circle is $L_\Phi\coloneqq2(\log 2)c_++\rho\log\rho$.
\end{theorem}

\begin{remark}
The level-17 rational certificate recorded in Appendix \ref{app:certificates} yields
\begin{align*}
    0.99281236<\phimin<0.99281934.
\end{align*}
\end{remark}

\begin{corollary}\label{cor:cluster-sets}
The normalized scalar and rate sequences satisfy
\begin{align*}
    \Clust\left(\frac{U_N}{N^p}\right)=[\phimin,1],
    \quad
    \Clust(N^ps_N)=\left[1,\frac1{\phimin}\right].
\end{align*}
In particular, neither sequence converges.
\end{corollary}

\begin{corollary}\label{cor:objective-phase}
Let $\theta_N = \{\log_2N\}$. For every $N\ge1$,
\begin{align}\label{eq:B-exact}
    B_N=\frac1{2N^p\Phi(\theta_N)-1}.
\end{align}
As $N \to \infty$,
\begin{align}\label{eq:B-asymptotic}
    B_N
    =\frac{N^{-p}}{2\Phi(\theta_N)}
    +O(N^{-2p}),
\end{align}
where the $O(N^{-2p})$ remainder is uniform in the dyadic phase $\theta_N$.
Furthermore,
\begin{align*}
    \Clust(N^pB_N)
    =\left[\frac12,\frac1{2\phimin}\right].
\end{align*}
Consequently, the normalized tight objective coefficient has no single asymptotic constant.
\end{corollary}

\begin{remark}
    The matching instances make $B_N$ tight for each corresponding optimized ConPP/OBS-S schedule. Since $B_N$ decreases strictly with $U_N$, balanced scalar optimization also makes this coefficient best among schedules generated recursively by ConPP or by basic s-composition. These statements do not assert exact finite-horizon minimax optimality over all predetermined schedules. The optimized ConPD/OBS-F schedules obey an asymmetric recursion and are treated separately in the next section.
\end{remark}

\begin{definition}[Definition~1 in \citet{GrimmerShuWangMOR}]\label{def:fcomposable}
A positive $n$-step schedule $h=(h_0,\ldots,h_{n-1})^\top$ is \emph{f-composable with rate $\eta>0$} if, for every $f\in\F_1$, every minimizer $x_*$, and every associated gradient-descent trajectory,
\begin{align*}
    f(x_n)-f_*
    \le\frac\eta2\norm{x_0-x_*}^2,
\end{align*}
and its rate satisfies the sum--product identities
\begin{align}\label{eq:f-rate-identity}
    \eta
    =\frac1{1+2\sum_{i=0}^{n-1}h_i}
    =\prod_{i=0}^{n-1}(h_i-1)^2.
\end{align}
The empty schedule is f-composable with rate one.
\end{definition}

\begin{proposition} \label{thm:obsf-sandwich}
For every $N\ge1$,
\begin{align}\label{eq:obsf-sandwich}
    2U_N-1\le W_N\le\rho U_N.
\end{align}
Consequently, if $t=\{\log_2m\}$, then
\begin{align*}
    \frac{1}{\rho\Phi(t)}
    \le C_m^F
    \le\frac{1}{2\Phi(t)}.
\end{align*}
\end{proposition}

\begin{theorem} \label{thm:obsf-continuous-phase}
There exists a unique positive Lipschitz function $\Psi_F:\mathbb T\to(0,\infty)$ such that the interpolation functions $\Psi_k$ converge uniformly to $\Psi_F$ on $[0,1]$:
\begin{align}\label{eq:obsf-uniform-phase}
    \norm{\Psi_k-\Psi_F}_{L^\infty([0,1])}
    \to0.
\end{align}
Equivalently, because the maximal interpolation mesh tends to zero and $\Psi_F$ is Lipschitz,
\begin{align*}
    \sup_{2^k\le N\le2^{k+1}}
    \left|N^p\eta^{\mathrm{F}}_N-\Psi_F(\{\log_2N\})\right|
    \to0.
\end{align*}
Thus
\begin{align*}
    \eta^{\mathrm{F}}_N=N^{-p}\Psi_F(\{\log_2N\})+o(N^{-p})
\end{align*}
as $N \to \infty$.
Moreover,
\begin{align}\label{eq:obsf-cluster-set}
    \Clust(N^p\eta^{\mathrm{F}}_N)
    =\Psi_F(\mathbb T)
    =[\min\Psi_F,\max\Psi_F].
\end{align}
Thus \eqref{eq:obsf-cluster-set} is the complete cluster interval of the normalized tight objective coefficient in \eqref{eq:obsf-objective-bound}. Combining this expansion with \eqref{eq:obsf-objective-bound} gives the following guarantee for the optimized ConPD/OBS-F schedules

\begin{align}\label{eq:obsf-objective-phase}
    f(x_{N-1})-f_*
    \le
    \left[N^{-p}\Psi_F(\{\log_2N\})+o(N^{-p})\right]
    \frac{L}{2}\norm{x_0-x_*}^2
\end{align}
where the $o(N^{-p})$ remainder has the same dyadic-block uniformity. One may take $2L_{\mathrm{obs}}\log 2$ as a Lipschitz constant for $\Psi_F$.
\end{theorem}

\begin{lemma} \label{lem:obsf-support}
Let $\xi_*\in(0,1)$ be the unique interior solution of
\begin{align}\label{eq:obsf-xi-equation}
    \xi^{2q-1}(2-\xi)=1,
\end{align}
and define
\begin{align*}
    \tau_*\coloneqq\frac{1-\xi_*}{2\xi_*^2},
    \quad
    B_{\mathrm{sup}}\coloneqq2^q\frac{1-\xi_*^{2q}}{(1-\xi_*)^q}.
\end{align*}
Then $B_{\mathrm{sup}}>2^q$ and, for all $u,w\ge0$,
\begin{align}\label{eq:obsf-support}
    \mathcal A(u,w)^q\le B_{\mathrm{sup}}u^q+w^q.
\end{align}
For $u,w>0$, equality holds if and only if $u/w=\tau_*$. Equality also holds when $u=0$, whereas the inequality is strict when $w=0<u$.
\end{lemma}

\begin{theorem} \label{cor:obsf-complete-phase}
The phase $\Psi_F$ is nonconstant and satisfies
\begin{align}\label{eq:obsf-final-enclosure}
    c_*<\min_{t\in\mathbb T}\Psi_F(t)
    <\max_{t\in\mathbb T}\Psi_F(t)
    \le\frac{c_*}{\phi_*}.
\end{align}
Consequently, the cluster interval in \eqref{eq:obsf-cluster-set} is nondegenerate and lies strictly above the sharp homogeneous support barrier. By \eqref{eq:obsf-objective-phase}, this is precisely the nondegenerate interval of asymptotic leading constants in the tight objective-gap guarantee for optimized ConPD/OBS-F schedules.
\end{theorem}

\begin{proposition} \label{prop:tree-recurrence}
    The sequence $\{T_N\}_{N\ge1}$ satisfies
    \begin{align}\label{eq:tree-recurrence}
        T_1=1,
        \quad
        T_N=\sum_{m\in\mathcal{M}_N}T_mT_{N-m}
        \quad(N\ge2).
    \end{align}
    More explicitly, write $N=\nu2^\ell$, where $\nu$ is odd. For $N\ge2$,
    \begin{enumerate}[label=(\roman*)]
        \item if $\nu=1$, then $T_N=T_{N/2}^2=1$;
        \item if $\nu>1$ and $\ell=0$, then
        \begin{align*}
            T_N=2T_{(N-1)/2}T_{(N+1)/2};
        \end{align*}
        \item if $\nu>1$ and $\ell\ge1$, setting
        \begin{align*}
            a=(\nu-1)2^{\ell-1},
            \quad
            b=\nu2^{\ell-1},
            \quad
            c=(\nu+1)2^{\ell-1},
        \end{align*}
        gives
        \begin{align}\label{eq:tree-three}
            T_N=2T_aT_c+T_b^2.
        \end{align}
    \end{enumerate}
\end{proposition}

\begin{proposition} \label{prop:subdivision-derivative}
There exists a bounded function $D:[1,2]\to[c_-,c_+]$ such that
\begin{align}\label{eq:F-integral}
    F(x)=1+\int_1^xD(u)\,\mathrm{d} u.
\end{align}
The function $D$ is continuous at every nondyadic point $x\in(1,2)$, and $F'(x)=D(x)$ there. At every interior dyadic point, both one-sided derivatives of $F$ exist.

For a binary path $\epsilon=\{\epsilon_i\}_{i\ge1}\in\{0,1\}^{\mathbb N}$, set $r_0=\rho$ and recursively define
\begin{align}\label{eq:r-bit}
    r_i=
    \begin{cases}
        T_0(r_{i-1}),&\epsilon_i=0,\\
        T_1(r_{i-1}),&\epsilon_i=1.
    \end{cases}
\end{align}
For $k\ge1$, define the partial product
\begin{align*}
    P_k(\epsilon)
    \coloneqq(\rho-1)\prod_{i=1}^{k}w_{\epsilon_i}(r_{i-1}).
\end{align*}
Then $P_k$ converges uniformly on the path space $\{0,1\}^{\mathbb N}$ to
\begin{align}\label{eq:D-product}
    P(\epsilon)\coloneqq
    (\rho-1)\prod_{i=1}^{\infty}w_{\epsilon_i}(r_{i-1})
\end{align}
in the precise sense that $\sup_\epsilon|P_k(\epsilon)-P(\epsilon)|\to0$. More precisely, with $M=1/[4\rho(\rho-1)]$,
\begin{align*}
    \sup_{\epsilon\in\{0,1\}^{\mathbb N}}
    \sum_{i=k+1}^{\infty}
    \left|\log w_{\epsilon_i}(r_{i-1})\right|
    \le4M(\rho-1)2^{-k}.
\end{align*}
If $x\in(1,2)$ is nondyadic and $x-1=0.\epsilon_1\epsilon_2\cdots$, then $D(x)=F'(x)=P(\epsilon)$. If an interior dyadic point $x_0$ has the two binary expansions
\begin{align*}
    x_0-1
    &=0.\epsilon_1\cdots\epsilon_m000\cdots\\
    &=0.\epsilon_1\cdots\epsilon_{m-1}0111\cdots,
    \quad \epsilon_m=1,
\end{align*}
then
\begin{align*}
    F'_+(x_0)&=P(\epsilon_1,\ldots,\epsilon_m,0,0,\ldots),\\
    F'_-(x_0)&=P(\epsilon_1,\ldots,\epsilon_{m-1},0,1,1,\ldots).
\end{align*}
\end{proposition}

\begin{corollary} \label{cor:strict-corner}
The two one-sided derivatives at $x=3/2$ satisfy
\begin{align}\label{eq:strict-corner}
    F'_-(3/2)>F'_+(3/2).
\end{align}
Consequently, $F$ is not differentiable at $3/2$ and is not continuously differentiable on $[1,2]$.
\end{corollary}

\begin{proposition} \label{prop:phase-cert}
For every $k\ge0$,
\begin{align*}
    \underline\phi_k\le\phimin\le\overline\phi_k,
    \quad
    0\le\overline\phi_k-\underline\phi_k\le\frac{p}{2^k}.
\end{align*}
The sequence $\{\underline\phi_k\}$ is nondecreasing, the sequence $\{\overline\phi_k\}$ is nonincreasing, and both converge to $\phimin$. All quantities through level $k$ are computable in $O(2^k)$ scalar operations.
\end{proposition}

\begin{lemma} \label{lem:obsf-local-comparisons}
For $x,y>0$,
\begin{align}
    \mathcal A(x,\rho y)&\le\rho\Kop(x,y),
    \label{eq:obsf-upper-local}\\
    \mathcal A(x,2y-1)&\ge2\Kop(x,y)-1,
    \quad x,y\ge1.
    \label{eq:obsf-lower-local}
\end{align}
\end{lemma}

\begin{lemma} \label{lem:obsf-discrete-modulus}
Set $L_U\coloneqq\max\{1,L_F\}$, and put $\phi_*\coloneqq\min\Phi$. With $U_0=0$, for every $m,N\ge1$,
\begin{align*}
    0<U_m-U_{m-1}&\le L_Um^{p-1},\\
    0<W_{N+1}-W_N&\le4L_UN^{p-1},\\
    |C_{N+1}-C_N|&\le\frac{4L_U+\rho p}{\phi_*^2N}.
\end{align*}
\end{lemma}

\begin{proposition} \label{prop:obsf-deficit}
For every $N\ge1$,
\begin{align*}
    W_N^q\le B_{\mathrm{sup}}N,
    \quad
    C_N=N^p\eta^{\mathrm{F}}_N\ge c_*.
\end{align*}
Define $E_N\coloneqq B_{\mathrm{sup}}N-W_N^q\ge0$. If $m$ is any maximizing pivot for $W_N$ and $r=N-m$, then
\begin{align}\label{eq:obsf-deficit-decomposition}
    E_N=B_{\mathrm{sup}}(m-U_m^q)+E_r+\sigma(U_m,W_r),
\end{align}
where
\begin{align*}
    \sigma(u,w)\coloneqq B_{\mathrm{sup}}u^q+w^q-\mathcal A(u,w)^q,
\end{align*}
and all three terms on the right-hand side of \eqref{eq:obsf-deficit-decomposition} are nonnegative.
\end{proposition}

\begin{lemma} \label{lem:obsf-strict-S-phase}
For every $x\in(1,2)$,
\begin{align*}
    F(x)<x^p.
\end{align*}
Equivalently, $\Phi(t)<1$ for every nonzero phase $t\in(0,1)$.
\end{lemma}

\begin{lemma} \label{lem:obsf-contact-fraction}
Write $r_*$ and $\alpha_*$ as in \eqref{eq:star}. Set $x_*\coloneqq2\alpha_*$. The contact fraction satisfies
\begin{align}\label{eq:obsf-contact-identity}
    \alpha_*=1-\xi_*^{2q},
    \quad
    1-\alpha_*=\xi_*^{2q},
\end{align}
and
\begin{align}\label{eq:obsf-contact-interval}
    \frac14<1-\alpha_*<\frac12.
\end{align}
In particular, $1/2<\alpha_*<1$ and $x_*\in(1,2)$.
\end{lemma}

\begin{lemma} \label{lem:obsf-dyadic-strict}
The dyadic-ray limit satisfies
\begin{align*}
    C_1^F=\lim_{k\to\infty}(2^k)^p\eta^{\mathrm{F}}_{2^k}>c_*.
\end{align*}
\end{lemma}

\begin{lemma} \label{lem:obsf-constant-rigidity}
If the phase profile in Theorem \ref{thm:obsf-continuous-phase} were constant, then it would be identically equal to $c_*$.
\end{lemma}

\begin{lemma} \label{lem:obsf-global-strict}
For every $t\in\mathbb T$,
\begin{align*}
    \Psi_F(t)>c_*.
\end{align*}
Consequently, $\min_{t\in\mathbb T}\Psi_F(t)>c_*$.
\end{lemma}

\begin{proposition} \label{prop:obsf-phase-enclosure}
For every $t\in\mathbb T$,
\begin{align*}
    \Psi_F(t)\le\frac{c_*}{\phi_*}.
\end{align*}
Equivalently, with $\Delta_F(t)=1/\Psi_F(t)$, one has $\Delta_F(t)\ge d_*\phi_*$.
\end{proposition}
